package com.rk.fooddelivery.common.idempotency;
import jakarta.persistence.*; import java.util.UUID; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes;
@Entity @Table(name="idempotency_records") public class IdempotencyRecord { @Id private UUID id; @Column(name="actor_id") private UUID actorId; private String operation; @Column(name="idempotency_key") private String key; @Column(name="request_hash") private String requestHash; @Column(name="resource_id") private UUID resourceId; @Column(name="response_status") private int responseStatus; @JdbcTypeCode(SqlTypes.JSON) @Column(name="response_body",columnDefinition="jsonb") private String responseBody; @Column(name="response_location") private String responseLocation; protected IdempotencyRecord(){} public IdempotencyRecord(UUID actorId,String operation,String key,String requestHash,UUID resourceId,int responseStatus,String responseBody,String responseLocation){this.id=UUID.randomUUID();this.actorId=actorId;this.operation=operation;this.key=key;this.requestHash=requestHash;this.resourceId=resourceId;this.responseStatus=responseStatus;this.responseBody=responseBody;this.responseLocation=responseLocation;} public String getRequestHash(){return requestHash;} public StoredResponse response(){return new StoredResponse(responseStatus,responseBody,responseLocation);} }
